import test from 'node:test';
import assert from 'node:assert/strict';
import { reviewerKeyFromWallet } from '../app/lib/wallet-address.mjs';
import { validateAgreement, agreementId, WALLET_AGREEMENT_SCHEMA, NATIVE_TARI_RESOURCE } from '../app/lib/accord.mjs';
import { createSapientAdapter } from '../app/lib/sapient.mjs';
import { createPledgeRecovery } from '../app/lib/recovery.mjs';

// Independent vector generated by Rust bech32 0.11.1 Bech32m, using public owner/view keys
// from the SDK's official component-address vectors. This address has no funds or private keys.
const address = 'otl_esm_17mufuvtwdwjlqhjj2rwaffwna5uae5pce7qje34p2jmwcz236f05faf4yzfxajqlh4drs7z9h6malpdfdgjwecv88z7ulf48sg4pwmganfp0v';
const key = 'f6f89e316e6ba5f05e5250ddd4a5d3ed39dcd038cf812cc6a154b6ec0951d25f';
const terms = {
  schema: WALLET_AGREEMENT_SCHEMA, title: 'Wallet review test', description: 'Synthetic test only.',
  network: 'esmeralda', resourceAddress: NATIVE_TARI_RESOURCE, creatorWalletAddress: address,
  milestones: [{ id: 'delivery', title: 'Deliver work', reviewer: { name: 'Reviewer', walletAddress: address }, refundEpoch: '1000' }],
};

test('reviewer key decoding matches an independent Rust Bech32m vector', () => {
  assert.equal(reviewerKeyFromWallet(address), key);
  for (const value of [address.slice(0, -1) + 'q', address.replace('otl_esm_', 'otl_igr_'), address.toUpperCase(), address + 'q', 'component_' + 'a'.repeat(64)]) {
    assert.throws(() => reviewerKeyFromWallet(value));
  }
});

test('v2 agreements use wallet-derived keys and reject secret or mismatched-key injection', async () => {
  const agreement = validateAgreement(terms);
  assert.equal(agreement.milestones[0].reviewer.publicKey, key);
  assert.equal(Object.hasOwn(agreement.milestones[0], 'hashLockHex'), false);
  assert.equal(await agreementId(agreement), await agreementId(terms));
  assert.throws(() => validateAgreement({ ...terms, milestones: [{ ...terms.milestones[0], hashLockHex: 'a'.repeat(64) }] }));
  assert.throws(() => validateAgreement({ ...terms, milestones: [{ ...terms.milestones[0], reviewer: { ...terms.milestones[0].reviewer, publicKey: 'b'.repeat(64) } }] }), /does not match/);
  await assert.rejects(createPledgeRecovery({ agreement, stageId: 'delivery', amount: '1', result: { transactionId: 'synthetic', ownCommitment: 'a'.repeat(64), outputMask: 'b'.repeat(64), conditions: [[{}], [{}]] } }), /legacy HTLC/);
});

function mockWallet(onAddress) {
  const calls = [];
  let listener;
  const provider = {
    isTariWallet: true,
    on(_event, fn) { listener = fn; return () => {}; },
    async request(args) {
      calls.push(args);
      switch (args.method) {
        case 'tari_requestAccounts': case 'tari_getAccounts': return ['component_reviewer'];
        case 'tari_getNetwork': return 'esmeralda';
        case 'tari_getCapabilities': return { transactionRequests: true, supportsPrivateFees: true, walletAddress: true };
        case 'tari_getWalletAddress': onAddress?.(() => listener?.()); return address;
        default: throw new Error('Unexpected request: ' + args.method);
      }
    },
  };
  return { calls, provider };
}

test('Sapient reviewer identity needs explicit connection and reads no balances or signatures', async () => {
  const mock = mockWallet();
  const adapter = createSapientAdapter({ provider: mock.provider, storage: null });
  await assert.rejects(adapter.getReviewerIdentity(), { code: 'NOT_CONNECTED' });
  await adapter.connect();
  assert.deepEqual(await adapter.getReviewerIdentity(), { walletAddress: address, publicKey: key });
  assert.equal(mock.calls.some(call => /Balances|ViewAccess|sign|TransactionRequest/.test(call.method)), false);
  adapter.dispose();
});

test('account changes while reading reviewer identity invalidate the response', async () => {
  const mock = mockWallet(change => change());
  const adapter = createSapientAdapter({ provider: mock.provider, storage: null });
  await adapter.connect();
  await assert.rejects(adapter.getReviewerIdentity(), { code: 'ACCOUNT_CHANGED' });
  assert.equal(adapter.getState().account, null);
});

test('unverified review deployments never cause a wallet request or spend', async () => {
  const mock = mockWallet();
  const adapter = createSapientAdapter({ provider: mock.provider, storage: null });
  await assert.rejects(adapter.approveMilestone({ agreement: terms, stageId: 'delivery', maxFee: '1000' }), { code: 'REVIEW_NOT_DEPLOYED' });
  assert.deepEqual(mock.calls, []);
  await assert.rejects(adapter.approveMilestone({ agreement: terms, stageId: 'absent' }), { code: 'INVALID_STAGE' });
});
